import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

// Min-reduction over a single dimension of a contiguous tensor.
// The tensor is viewed as [outer, reduce, inner] and we reduce over the
// middle ("reduce") dimension. For the target workload dim=1 of a
// [128, 4096, 4095] tensor the kernel is purely DRAM-bandwidth bound
// (no data reuse), so the goal is to maximize the number of
// outstanding coalesced loads.
//
// Optimization: thread coarsening (register blocking over outputs).
// Each thread owns TWO consecutive (outer, inner) output elements and
// strides over the reduction dimension for both. The two output
// streams are interleaved with a 4-way unrolled reduction loop,
// giving eight independent coalesced loads in flight per thread.
// This raises memory-level parallelism per warp (more outstanding
// cache lines), which pushes DRAM utilization higher for this
// streaming reduction, while consecutive threads still touch
// consecutive addresses, so reads stay fully coalesced.
// A grid-stride loop is used so the launch can be sized to exactly one
// full wave of resident blocks, eliminating the partial-wave tail.
__global__ void min_reduce_dim_kernel(const float* __restrict__ x,
                                      float* __restrict__ out,
                                      long long outer,
                                      long long reduce,
                                      long long inner) {
    long long total = outer * inner;
    long long pairs = (total + 1) >> 1;
    long long stride = (long long)gridDim.x * blockDim.x;
    for (long long p = (long long)blockIdx.x * blockDim.x + threadIdx.x;
         p < pairs; p += stride) {
        long long idx0 = 2 * p;
        long long idx1 = idx0 + 1;
        bool has1 = idx1 < total;
        long long o0 = idx0 / inner;
        long long j0 = idx0 - o0 * inner;
        long long o1 = has1 ? (idx1 / inner) : o0;
        long long j1 = has1 ? (idx1 - o1 * inner) : j0;
        const float* p0 = x + o0 * reduce * inner + j0;
        const float* p1 = x + o1 * reduce * inner + j1;
        // Four independent partial minima per output (eight total)
        // shorten the loop-carried fminf dependency chains and keep
        // many independent coalesced loads in flight per thread.
        float a0 = p0[0];
        float a1 = a0;
        float a2 = a0;
        float a3 = a0;
        float b0 = p1[0];
        float b1 = b0;
        float b2 = b0;
        float b3 = b0;
        p0 += inner;
        p1 += inner;
        long long i = 1;
        for (; i + 3 < reduce; i += 4) {
            float v00 = __ldcs(p0);
            float v01 = __ldcs(p0 + inner);
            float v02 = __ldcs(p0 + 2 * inner);
            float v03 = __ldcs(p0 + 3 * inner);
            float v10 = __ldcs(p1);
            float v11 = __ldcs(p1 + inner);
            float v12 = __ldcs(p1 + 2 * inner);
            float v13 = __ldcs(p1 + 3 * inner);
            a0 = fminf(a0, v00);
            a1 = fminf(a1, v01);
            a2 = fminf(a2, v02);
            a3 = fminf(a3, v03);
            b0 = fminf(b0, v10);
            b1 = fminf(b1, v11);
            b2 = fminf(b2, v12);
            b3 = fminf(b3, v13);
            p0 += 4 * inner;
            p1 += 4 * inner;
        }
        for (; i < reduce; ++i) {
            a0 = fminf(a0, __ldcs(p0));
            b0 = fminf(b0, __ldcs(p1));
            p0 += inner;
            p1 += inner;
        }
        __stcs(out + idx0, fminf(fminf(a0, a1), fminf(a2, a3)));
        if (has1) __stcs(out + idx1, fminf(fminf(b0, b1), fminf(b2, b3)));
    }
}

torch::Tensor min_reduce(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    auto xc = x.contiguous();

    int64_t nd = xc.dim();
    TORCH_CHECK(nd >= 1, "x must have at least one dimension");
    if (dim < 0) dim += nd;
    TORCH_CHECK(dim >= 0 && dim < nd, "dim out of range");

    long long outer = 1, inner = 1;
    for (int64_t i = 0; i < dim; ++i) outer *= xc.size(i);
    long long reduce = xc.size(dim);
    for (int64_t i = dim + 1; i < nd; ++i) inner *= xc.size(i);

    std::vector<int64_t> out_shape;
    out_shape.reserve(nd - 1);
    for (int64_t i = 0; i < nd; ++i) {
        if (i != dim) out_shape.push_back(xc.size(i));
    }
    auto out = at::empty(out_shape, xc.options());

    long long total = outer * inner;
    if (total == 0 || reduce == 0) return out;

    const int threads = 256;
    long long pairs = (total + 1) / 2;
    long long blocksNeeded = (pairs + threads - 1) / threads;
    // Size the grid to one full wave of resident blocks so there is no
    // partial-wave tail; the grid-stride loop covers all outputs.
    int dev = 0;
    cudaGetDevice(&dev);
    int sms = 0;
    cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, dev);
    int blocksPerSm = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(
        &blocksPerSm, min_reduce_dim_kernel, threads, 0);
    if (blocksPerSm < 1) blocksPerSm = 1;
    long long wave = (long long)sms * blocksPerSm;
    long long blocks = blocksNeeded < wave ? blocksNeeded : wave;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    min_reduce_dim_kernel<<<(unsigned int)blocks, threads, 0, stream>>>(
        xc.data_ptr<float>(), out.data_ptr<float>(), outer, reduce, inner);
    return out;
}
"""

cpp_src = "torch::Tensor min_reduce(torch::Tensor x, int64_t dim);"

_module = load_inline(
    name="min_reduce_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["min_reduce"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Min reduction over a specific dimension implemented with a custom CUDA kernel.
    """

    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _module.min_reduce(x, self.dim)

